import { SendAurora } from "@/components/control-ui/extensions/send-aurora";
import type { ControlUiSkin } from "@/components/control-ui/skin";

export const skin: ControlUiSkin = {
  id: "cuicui",
  sidebarLayout: "sidebar",
  sidebarWidth: "20rem",
  adornments: {
    button: {
      layer: (ctx) =>
        ctx.variant === "solid" && ctx.tone !== "danger" ? (
          <span
            aria-hidden
            className="cuicui-animated-gradient pointer-events-none absolute inset-0 rounded-[inherit] opacity-40 mix-blend-overlay"
          />
        ) : null,
    },
    "chat-composer": {
      "send-layer": (ctx) => (
        <SendAurora
          sendCount={ctx.sendCount}
          colors={["var(--cuicui-pink)", "var(--cuicui-orange)", "var(--cuicui-yellow)", "var(--cuicui-sky)", "var(--cuicui-blue)"]}
        />
      ),
    },
  },
};

[data-skin="cuicui"] {
  --cuicui-sky: oklch(0.7676 0.1305 225.406);
  --cuicui-violet: oklch(0.6131 0.2067 283.833);
  --cuicui-rose: oklch(0.6851 0.1761 14.132);
  --cuicui-orange: oklch(0.7259 0.1609 48.691);
  --cuicui-yellow: oklch(0.8659 0.1539 86.484);
  --cuicui-pink: oklch(0.651 0.2092 346.41);
  --cuicui-blue: oklch(0.6871 0.1707 250.704);
  --cuicui-mint: oklch(0.8983 0.0973 174.414);
  --cuicui-gradient: linear-gradient(135deg, var(--cuicui-sky), var(--cuicui-violet), var(--cuicui-rose), var(--cuicui-orange));
  /* Same hues held at one lightness, so a white label clears AA wherever it lands on the sweep. */
  --cuicui-stops-legible:
    oklch(from var(--cuicui-sky) 0.46 c h), oklch(from var(--cuicui-violet) 0.46 c h), oklch(from var(--cuicui-rose) 0.46 c h),
    oklch(from var(--cuicui-orange) 0.46 c h);
  --cuicui-gradient-text: linear-gradient(to right, var(--cuicui-sky), var(--cuicui-violet), var(--cuicui-rose), var(--cuicui-orange));
  --cuicui-gradient-top: linear-gradient(-45deg, var(--cuicui-yellow), var(--cuicui-pink), var(--cuicui-blue), var(--cuicui-mint));
  --cuicui-gradient-soft: linear-gradient(
    135deg,
    oklch(from var(--cuicui-sky) l c h / 0.16),
    oklch(from var(--cuicui-violet) l c h / 0.18),
    oklch(from var(--cuicui-orange) l c h / 0.16)
  );
  --cuicui-noise: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' version='1.1' xmlnsXlink='http://www.w3.org/1999/xlink' viewBox='0 0 700 700' width='700' height='700' opacity='1'%3e%3ctitle%3enoise%3c/title%3e%3cdefs%3e%3cfilter id='nnnoise-filter' x='-20%25' y='-20%25' width='140%25' height='140%25' filterUnits='objectBoundingBox' primitiveUnits='userSpaceOnUse' color-interpolation-filters='linearRGB'%3e%3cfeTurbulence type='fractalNoise' baseFrequency='0.2' numOctaves='4' seed='15' stitchTiles='stitch' x='0%25' y='0%25' width='100%25' height='100%25' result='turbulence'/%3e%3cfeSpecularLighting surfaceScale='5' specularConstant='0.8' specularExponent='20' lighting-color='white' x='0%25' y='0%25' width='100%25' height='100%25' in='turbulence' result='specularLighting'%3e%3cfeDistantLight azimuth='3' elevation='96'/%3e%3c/feSpecularLighting%3e%3cfeColorMatrix type='saturate' values='0' x='0%25' y='0%25' width='100%25' height='100%25' in='specularLighting' result='colormatrix'/%3e%3c/filter%3e%3c/defs%3e%3crect width='700' height='700' fill='black'/%3e%3crect width='700' height='700' fill='white' filter='url(%23nnnoise-filter)'/%3e%3c/svg%3e");
  --cuicui-page-from: oklch(1 0 0);
  --cuicui-page-to: oklch(0.985 0 0);
  --cuicui-page-bg: linear-gradient(to top, var(--cuicui-page-from), var(--cuicui-page-to));
  --cuicui-main-container: oklch(0.985 0 0);
  --cuicui-container-border: oklch(0.708 0 0 / 0.2);
  --cuicui-surface-bg: oklch(1 0 0 / 0.84);
  --cuicui-control-bg: oklch(0.922 0 0 / 0.42);
  --cuicui-control-hover: oklch(0.922 0 0 / 0.28);
  --cuicui-field-bg: oklch(1 0 0 / 0.9);
  --cuicui-border: oklch(from var(--foreground) l c h / 0.16);
  --cuicui-control-shadow: 0 1px 2px oklch(from var(--shadow-color) l c h / 0.06);
  --cuicui-solid-shadow: inset 0 1px 0 oklch(1 0 0 / 0.28), 0 8px 24px oklch(from var(--primary) l c h / 0.24);
}

:where(.dark) [data-skin="cuicui"],
.dark[data-skin="cuicui"] {
  --cuicui-page-from: oklch(0.145 0 0);
  --cuicui-page-to: oklch(0.269 0 0);
  --cuicui-main-container: oklch(0.173 0 0);
  --cuicui-surface-bg: oklch(0.205 0 0 / 0.82);
  --cuicui-control-bg: oklch(0.708 0 0 / 0.14);
  --cuicui-control-hover: oklch(0.708 0 0 / 0.2);
  --cuicui-field-bg: oklch(0.173 0 0 / 0.76);
  --cuicui-border: oklch(1 0 0 / 0.13);
  --cuicui-control-shadow: 0 1px 2px oklch(0 0 0 / 0.18);
}

@layer base {
  :root[data-skin="cuicui"] body {
    min-height: 100dvh;
    background-color: var(--cuicui-page-from);
    background-image: var(--cuicui-page-bg);
  }

  :root[data-skin="cuicui"] body::after {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 9999;
    pointer-events: none;
    user-select: none;
    background-image: var(--cuicui-noise);
    background-size: 400px;
    opacity: 0.05;
    filter: invert(1);
  }

  :root.dark[data-skin="cuicui"] body::after {
    filter: none;
  }
}

@layer components {
  [data-skin="cuicui"]
    :where(
      [data-control-ui="button"][data-slot="root"][data-control-family="button"],
      [data-control-ui="toggle"][data-slot="root"][data-control-family="button"]
    ) {
    --cui-button-gap: 0.375rem;
    --cui-button-bg: var(--cuicui-control-bg);
    --cui-button-foreground: var(--foreground);
    --cui-button-hover-bg: var(--cuicui-control-hover);
    --cui-button-hover-foreground: var(--foreground);
    --cui-button-shadow: var(--cuicui-control-shadow);
    --cui-button-press-scale: 0.96;
    border: 1px solid var(--cuicui-border);
  }

  [data-skin="cuicui"]
    :where(
      [data-control-ui="button"][data-slot="root"][data-variant="solid"][data-control-family="button"],
      [data-control-ui="toggle"][data-slot="root"][data-variant="solid"][data-control-family="button"]
    ) {
    --cui-button-bg: var(--primary);
    --cui-button-foreground: oklch(1 0 0);
    --cui-button-hover-bg: var(--primary);
    --cui-button-hover-foreground: oklch(1 0 0);
    --cui-button-press-bg: var(--primary);
    --cui-button-shadow: var(--cuicui-solid-shadow);
    --cui-button-bg-image: linear-gradient(135deg, var(--cuicui-stops-legible));
    border-color: transparent;
  }

  [data-skin="cuicui"]
    :where(
      [data-control-ui="button"][data-slot="root"][data-tone="danger"][data-variant="solid"][data-control-family="button"],
      [data-control-ui="toggle"][data-slot="root"][data-tone="danger"][data-variant="solid"][data-control-family="button"]
    ) {
    --cui-button-bg: var(--destructive);
    --cui-button-foreground: var(--destructive-foreground);
    --cui-button-hover-bg: var(--destructive);
    --cui-button-hover-foreground: var(--destructive-foreground);
    --cui-button-press-bg: var(--destructive);
    --cui-button-shadow: var(--cuicui-control-shadow);
    --cui-button-bg-image: none;
    border-color: transparent;
  }

  @media (hover: hover) {
    [data-skin="cuicui"]
      :where(
        [data-control-ui="button"][data-tone="danger"][data-variant="solid"][data-control-family="button"]:hover,
        [data-control-ui="toggle"][data-tone="danger"][data-variant="solid"][data-control-family="button"]:hover
      ) {
      filter: brightness(1.05);
    }
  }

  [data-skin="cuicui"]
    :where(
      [data-slot="root"][data-variant="inverse"][data-control-family="toolbar"]
        [data-control-ui="button"][data-slot="root"][data-control-family="button"]
    ) {
    --cui-button-bg: transparent;
    --cui-button-foreground: oklch(from var(--background) l c h / 0.7);
    --cui-button-hover-bg: oklch(from var(--background) l c h / 0.1);
    --cui-button-hover-foreground: var(--background);
    --cui-button-press-bg: oklch(from var(--background) l c h / 0.12);
    --cui-button-active-bg: var(--background);
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-bg: var(--background);
    --cui-button-shadow: 0 0 transparent;
    --cui-button-active-shadow: 0 0 transparent;
  }

  [data-skin="cuicui"] .cuicui-gradient-fill {
    background-color: var(--primary);
    background-image: var(--cuicui-gradient);
  }

  [data-skin="cuicui"] .cuicui-gradient-text {
    background-image: var(--cuicui-gradient-text);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
  }

  [data-skin="cuicui"] .cuicui-animated-gradient {
    background-image: var(--cuicui-gradient-top);
    background-size: 400% 400%;
    animation: cuicui-gradient-animation 5s ease infinite;
  }

  [data-skin="cuicui"] :where([data-slot="root"][data-control-family="tabs"]) {
    --cui-tabs-trigger-radius: calc(var(--radius-control) * 0.78);
    --cui-tabs-list-radius: var(--radius-control);
    --cui-tabs-list-padding: 0.25rem;
    --cui-tabs-list-background: var(--cuicui-control-bg);
    --cui-tabs-active-foreground: var(--primary-foreground);
    --cui-tabs-indicator-background: linear-gradient(to right, var(--cuicui-stops-legible));
    --cui-tabs-indicator-shadow: 0 0 20px oklch(from var(--primary) l c h / 0.22);
  }

  [data-skin="cuicui"] [data-slot="tab"][data-control-family="tabs"] {
    letter-spacing: -0.01em;
  }
}

@keyframes cuicui-gradient-animation {
  0% {
    -webkit-background-position: 0% 50%;
    background-position: 0% 50%;
  }

  50% {
    -webkit-background-position: 100% 50%;
    background-position: 100% 50%;
  }

  100% {
    -webkit-background-position: 0% 50%;
    background-position: 0% 50%;
  }
}

@layer components {
  @media (prefers-reduced-motion: reduce) {
    [data-skin="cuicui"] .cuicui-animated-gradient {
      animation: none;
    }
  }
}

@layer components {
  [data-skin="cuicui"]
    :where([data-control-family="popup"][data-popup-part="surface"], [data-control-family="popup"][data-popup-part="list-surface"]) {
    --cui-popup-radius: var(--radius-popover);
    --cui-popup-background: oklch(from var(--popover) l c h / 0.9);
    --cui-popup-foreground: var(--popover-foreground);
    --cui-popup-border-color: var(--cuicui-border);
    --cui-popup-border-width: 1px;
    --cui-popup-shadow: var(--shadow-pop);
    --cui-popup-backdrop-filter: blur(var(--backdrop-blur-popover));
  }

  [data-skin="cuicui"] :where([data-popup-part="list-surface"]) {
    padding: 0.25rem;
  }

  [data-skin="cuicui"] :where([data-popup-part="item"]) {
    padding: 0.25rem 0.625rem;
    font-size: 0.8125rem;
  }

  [data-skin="cuicui"] :where([data-popup-part="label"]) {
    padding: 0.25rem 0.5rem;
    font-size: 0.6875rem;
  }

  [data-skin="cuicui"]
    :where(
      [data-control-family="popup"][data-popup-part="surface"],
      [data-control-family="popup"][data-popup-part="list-surface"],
      [data-control-family="popup"][data-popup-part="bar"]
    ) {
    --cui-popup-item-radius: var(--radius-popup-item);
    --cui-popup-item-highlight-background: var(--cuicui-control-bg);
    --cui-popup-item-disabled-opacity: 0.45;
    --cui-popup-separator-color: var(--cuicui-border);
  }

  [data-skin="cuicui"] :where([data-popup-part="separator"]) {
    margin-inline: 0.25rem;
  }

  [data-skin="cuicui"] :where([data-popup-part="shortcut"]) {
    margin-inline-start: auto;
    font-size: 0.6875rem;
    letter-spacing: 0.025em;
  }

  [data-skin="cuicui"] :where([data-control-ui="navigation-menu"][data-slot="viewport"][data-control-family="popup"]) {
    padding: 0.25rem;
  }

  [data-skin="cuicui"]
    :where(
      [data-control-ui="select"][data-slot="trigger"][data-control-family="button"],
      [data-control-ui="dropdown-menu"][data-slot="trigger"][data-control-family="button"],
      [data-control-ui="menubar"][data-slot="trigger"][data-control-family="button"]
    ) {
    --cui-button-radius: var(--radius-control);
    --cui-button-bg: var(--cuicui-control-bg);
    --cui-button-foreground: var(--foreground);
    --cui-button-hover-bg: var(--cuicui-control-hover);
    --cui-button-hover-foreground: var(--foreground);
    --cui-button-shadow: var(--cuicui-control-shadow);
    --cui-button-press-scale: 0.96;
    border: 1px solid var(--cuicui-border);
  }
  [data-skin="cuicui"]
    :where(
      [data-control-ui="dialog"][data-slot="content"][data-surface="modal"][data-control-family="popup"],
      [data-control-ui="alert-dialog"][data-slot="content"][data-surface="modal"][data-control-family="popup"]
    ) {
    --cui-popup-radius: var(--radius-panel);
    --cui-popup-background: var(--cuicui-surface-bg);
    --cui-popup-border-color: var(--cuicui-border);
    --cui-popup-border-width: 1px;
    --cui-popup-shadow: var(--shadow-soft);
    --cui-popup-backdrop-filter: blur(var(--backdrop-blur-popover));
  }

  [data-skin="cuicui"]
    :where(
      [data-control-ui="dialog"][data-popup-part="surface"][data-control-family="popup"],
      [data-control-ui="alert-dialog"][data-popup-part="surface"][data-control-family="popup"]
    ) {
    padding: 1.5rem;
  }

  [data-skin="cuicui"] :where([data-control-ui="dialog"][data-slot="title"][data-control-family="popup"]) {
    font-size: 0.9375rem;
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  [data-skin="cuicui"] :where([data-control-ui="tooltip"][data-popup-part="surface"][data-control-family="popup"]) {
    --cui-popup-radius: var(--radius-control);
    --cui-popup-background: var(--popover);
    --cui-popup-border-color: var(--cuicui-border);
    --cui-popup-border-width: 1px;
    --cui-popup-shadow: var(--shadow-pop);
    padding: 0.375rem 0.625rem;
    font-size: 0.75rem;
  }
}

@layer components {
  [data-skin="cuicui"] :where([data-control-family="field"][data-control="true"]) {
    --cui-field-radius: var(--radius-control);
    --cui-field-background: var(--cuicui-field-bg);
    --cui-field-foreground: var(--foreground);
    --cui-field-border-color: var(--input);
    --cui-field-border-width: 1px;
    --cui-field-shadow: var(--cuicui-control-shadow);
    --cui-field-focus-border-color: var(--input);
  }
}

@layer components {
  [data-skin="cuicui"] :where([data-slot="root"][data-control-family="card"]) {
    --cui-card-radius: var(--radius-panel);
    --cui-card-background: var(--cuicui-surface-bg);
    --cui-card-border-color: var(--cuicui-border);
    --cui-card-border-width: 1px;
    --cui-card-shadow: var(--shadow-soft);
    --cui-card-backdrop-filter: blur(var(--backdrop-blur-popover));
  }
}
@layer components {
  [data-skin="cuicui"] :where([data-control-ui="command"][data-slot="root"][data-control-family="popup"]) {
    --cui-popup-radius: var(--radius-popover);
    --cui-popup-background: oklch(from var(--popover) l c h / 0.9);
    --cui-popup-border-color: var(--cuicui-border);
    --cui-popup-border-width: 1px;
    --cui-popup-shadow: var(--shadow-pop);
    --cui-popup-backdrop-filter: blur(var(--backdrop-blur-popover));
    overflow: hidden;
    padding: 0.25rem;
  }

  [data-skin="cuicui"] :where([data-control-ui="command"][data-popup-part="bar"][data-control-family="popup"]) {
    --cui-popup-separator-color: var(--cuicui-border);
    --cui-popup-item-radius: var(--radius-popup-item);
    --cui-popup-item-highlight-background: var(--cuicui-control-bg);
    --cui-popup-item-disabled-opacity: 0.45;
  }

  /* The toast reads as a solid panel, not the translucent menu surface. */
  [data-skin="cuicui"] :where([data-control-ui="toast"][data-popup-part="surface"][data-control-family="popup"]) {
    --cui-popup-radius: var(--radius-panel);
    --cui-popup-background: var(--cuicui-surface-bg);
  }

  [data-skin="cuicui"] :where([data-slot="wrapper"][data-control-family="sidebar"]) {
    position: relative;
    isolation: isolate;
  }

  [data-skin="cuicui"] :where([data-slot="inner"][data-control-family="sidebar"]) {
    padding: calc(var(--spacing) * 3);
  }

  [data-skin="cuicui"] :where([data-slot="menu-button"][data-control-family="sidebar"]) {
    border: 1px solid transparent;
    padding-inline: calc(var(--spacing) * 3);
    font-size: var(--text-sm);
    line-height: var(--text-sm--line-height);
    font-weight: var(--font-weight-medium);
  }

  [data-skin="cuicui"] :where([data-slot="wrapper"][data-control-family="sidebar"]) {
    --cui-sidebar-wrapper-background: var(--cuicui-page-from);
    --cui-sidebar-wrapper-background-image: var(--cuicui-page-bg);
    --cui-sidebar-inset-background: var(--cuicui-page-from);
    --cui-sidebar-inset-background-image: var(--cuicui-page-bg);
  }

  [data-skin="cuicui"] :where([data-slot="root"][data-control-family="sidebar"]) {
    --cui-sidebar-inner-background: transparent;
    --cui-sidebar-inner-border-width: 0px;
    --cui-sidebar-inner-radius: 0px;
    --cui-sidebar-inner-shadow: none;
    --cui-sidebar-menu-button-radius: var(--radius);
    --cui-sidebar-menu-button-foreground: oklch(0 0 0 / 0.55);
    --cui-sidebar-menu-button-hover-background: oklch(0 0 0 / 0.05);
    --cui-sidebar-menu-button-hover-foreground: oklch(0 0 0 / 0.7);
    --cui-sidebar-menu-button-active-background: oklch(0 0 0 / 0.05);
    --cui-sidebar-menu-button-active-foreground: oklch(0 0 0 / 0.7);
    --cui-sidebar-group-label-foreground: var(--color-neutral-500);
  }

  [data-skin="cuicui"] :where([data-slot="group-label"][data-control-family="sidebar"]) {
    padding-inline: calc(var(--spacing) * 3);
    padding-block: var(--spacing);
    font-size: var(--text-xs);
    line-height: var(--text-xs--line-height);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--tracking-tight);
  }

  .dark[data-skin="cuicui"] :where([data-slot="root"][data-control-family="sidebar"]),
  :where(.dark) [data-skin="cuicui"] :where([data-slot="root"][data-control-family="sidebar"]) {
    --cui-sidebar-menu-button-foreground: oklch(1 0 0 / 0.55);
    --cui-sidebar-menu-button-hover-background: oklch(1 0 0 / 0.1);
    --cui-sidebar-menu-button-hover-foreground: oklch(1 0 0 / 0.7);
    --cui-sidebar-menu-button-active-background: oklch(1 0 0 / 0.1);
    --cui-sidebar-menu-button-active-foreground: oklch(1 0 0 / 0.8);
    --cui-sidebar-group-label-foreground: var(--color-neutral-400);
  }

  [data-skin="cuicui"] :where([data-slot="content"][data-control-family="sidebar-layout"]) {
    border: 1px solid var(--cuicui-container-border);
    border-radius: var(--radius);
    background-color: var(--cuicui-main-container);
    box-shadow: none;
  }

  [data-skin="cuicui"] :where([data-slot="root"][data-control-family="alert"]) {
    --cui-alert-radius: var(--radius-panel);
    --cui-alert-background: var(--cuicui-surface-bg);
    --cui-alert-border-color: var(--cuicui-border);
  }

  [data-skin="cuicui"] :where([data-slot="root"][data-control-family="badge"]) {
    --cui-badge-radius: 9999px;
    --cui-badge-background: var(--cuicui-control-bg);
    --cui-badge-foreground: var(--foreground);
    --cui-badge-border-color: var(--cuicui-border);
  }

  [data-skin="cuicui"] :where([data-slot="root"][data-control-family="item"]) {
    --cui-item-radius: var(--radius-control);
    --cui-item-hover-background: var(--cuicui-control-bg);
    --cui-item-hover-border-color: var(--cuicui-border);
    --cui-item-border-width: 1px;
  }

  [data-skin="cuicui"] :where([data-slot="root"][data-control-family="empty"]) {
    --cui-empty-radius: var(--radius-panel);
    --cui-empty-background: var(--cuicui-surface-bg);
    --cui-empty-border-color: var(--cuicui-border);
    --cui-empty-border-width: 1px;
    --cui-empty-border-style: dashed;
    --cui-empty-media-radius: var(--radius-control);
    --cui-empty-media-background: var(--cuicui-gradient-soft);
  }

  [data-skin="cuicui"] :where([data-control-ui="slider"][data-slot="root"][data-control-family="range"]) {
    --cui-range-track-background: var(--cuicui-control-bg);
    --cui-range-indicator-background: var(--primary);
    --cui-range-thumb-radius: var(--radius-control);
    --cui-range-thumb-background: var(--cuicui-control-bg);
    --cui-range-thumb-border-color: var(--cuicui-border);
